class JobQueue:
    def __init__(self):
        self.pending = {}

    def enqueue(self, key, payload, due):
        self.pending[key] = {"key": key, "payload": payload, "due": due}

    def drain(self, now, handler):
        delivered = 0
        for key, job in list(self.pending.items()):
