'use strict';
const currencyLabel = '¥';
function makeInvoice(lines, rate, record = () => {}) {
  if (!Array.isArray(lines)) throw new TypeError('lines');
  if (!Number.isFinite(rate) || rate < 0) throw new RangeError('rate');
  let subtotal = 0;
  for (const line of lines) {
    if (!Number.isSafeInteger(line.priceCents) || line.priceCents < 0 ||
        !Number.isSafeInteger(line.quantity) || line.quantity < 0) throw new RangeError('line');
    subtotal += line.priceCents * line.quantity;
  }
  const totalCents = Math.round(subtotal * (1 + rate));
  const label = currencyLabel + (totalCents / 100).toFixed(2);
  record(label, totalCents);
  return Object.freeze({ totalCents, label });
}
function createFeed() {
  const listeners = new Set();
  let closed = false;
  return {
    subscribe(fn) {
      if (closed) throw new Error('closed');
      listeners.add(fn);
      return () => listeners.delete(fn);
    },
    publish(value) {
      if (closed) return false;
      const batch = [...listeners];
      queueMicrotask(() => {
        for (const fn of batch) if (listeners.has(fn)) fn(value);
      });
      return true;
    },
    close() { closed = true; listeners.clear(); }
  };
}
module.exports = { makeInvoice, createFeed };

originalFixtures.refactor/test.cjs:
const assert = require('node:assert/strict');
const {makeInvoice, createFeed} = require('./index.cjs');
(async () => {
  assert.equal(makeInvoice([{priceCents: 105, quantity: 2}], 0.1).totalCents, 231);
  assert.throws(() => makeInvoice([], -1), RangeError);
  const feed = createFeed(), seen = [];
  const off = feed.subscribe(x => seen.push(x));
  feed.publish('a'); off();
  await new Promise(r => setImmediate(r));
  assert.deepEqual(seen, []);
  feed.close(); feed.close();
  assert.equal(feed.publish('b'), false);
  assert.throws(() => feed.subscribe(() => {}), /closed/);
  console.log('PASS public consumer');
})();

